/*!40000 ALTER TABLE `bbs_category` DISABLE KEYS */;
INSERT INTO `bbs_category` VALUES (1,'通用社区','覆盖全场景通用事务，聚焦跨板块协作、基础问题解决与全员信息同步，是企业全域沟通枢纽。\n','el-icon-cpu',1,'0',176,'admin','2026-02-03 14:21:23','',NULL,''),(2,'产品社区','围绕产品全生命周期，汇聚需求研讨、研发协同、迭代优化与产品问题攻坚的产品相关人员。\n','el-icon-s-promotion',2,'0',1,'admin','2026-02-03 14:21:23','',NULL,''),(3,'网络社区','聚焦网络架构、运维保障、故障排查与安全防护，是技术团队处理网络相关事务的交流平台。\n','el-icon-document',3,'0',2,'admin','2026-02-03 14:21:23','',NULL,''),(4,'人力社区','专注人力资源全模块，涵盖招聘、薪酬、员工关系、培训发展，服务企业人力管理与员工咨询。\n','el-icon-sunny',4,'0',2,'admin','2026-02-03 14:21:23','',NULL,''),(5,'财务社区','围绕企业财务工作，开展账务处理、预算管控、报销审核、税务筹划的财务人员专属交流阵地。\n\n\n\n\n\n\n\n每个社区的具体功能有哪些？\n如何加入这些社区？\n这些社区之间有什么联系和区别？\n','el-icon-question',5,'0',2,'admin','2026-02-03 14:21:23','',NULL,'');
/*!40000 ALTER TABLE `bbs_category` ENABLE KEYS */;
