DROP TABLE IF EXISTS `bbs_idea_progress`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bbs_idea_progress` (
  `progress_id` bigint NOT NULL AUTO_INCREMENT,
  `idea_id` bigint NOT NULL,
  `progress_stage` varchar(100) NOT NULL,
  `progress_desc` varchar(1000) DEFAULT NULL,
  `progress_percent` int NOT NULL DEFAULT '0',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `status_enum` varchar(30) DEFAULT NULL COMMENT '状态枚举',
  `updater_user_id` varchar(64) DEFAULT NULL COMMENT '更新人ID',
  `updater_nick_name` varchar(100) DEFAULT NULL COMMENT '更新人昵称',
  `attachment_urls` text COMMENT '落地资料/附件URL',
  PRIMARY KEY (`progress_id`),
  KEY `idx_idea_progress_idea` (`idea_id`),
  CONSTRAINT `fk_idea_progress_idea` FOREIGN KEY (`idea_id`) REFERENCES `bbs_idea_proposal` (`idea_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=98 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Innovation execution progress';
/*!40101 SET character_set_client = @saved_cs_client */;

