L,'2','张三','2026-11-06 22:30:30','2026-11-07 17:33:41','product','11','111','1111','all','','','','0','L1',NULL,NULL,NULL,'0',0,NULL,0,0,'2026-11-13 22:30:30','2'),(27,'1','11\n\n111\n\n1111','','L2_REVIEWING',8.00,NULL,'2','张三','2026-11-05 23:22:15','2026-11-07 17:33:41','product','11','111','1111','all','','','','0','L2',NULL,NULL,NULL,'0',0,NULL,0,0,'2026-11-12 23:40:35','2'),(28,'办公线上报表自动汇总','每周需要人工整理多份业务报表，复制粘贴耗时长，容易出现录入错误。\n\n对接各业务数据源，开发自动汇总脚本，一键生成合并报表。\n\n减少人工统计时间，避免手工录入错误，释放人力做其他工作。','每周可节省报表统计工时约 4 小时，消除人工汇总带来的数据偏差，保障业务数据时效性，降低沟通核对成本。','L3_REVIEWING',8.00,NULL,'3','李四','2026-11-07 22:43:13','2026-11-07 22:49:06','cost','每周需要人工整理多份业务报表，复制粘贴耗时长，容易出现录入错误。','对接各业务数据源，开发自动汇总脚本，一键生成合并报表。','减少人工统计时间，避免手工录入错误，释放人力做其他工作。','all','','同部门曾尝试用 Excel 函数汇总报表，数据量大时卡顿、刷新缓慢，无法满足多数据源同步更新需求。','业务支撑组','0','L3',NULL,NULL,NULL,'0',0,NULL,0,0,'2026-11-14 22:49:06','0'),(29,'建立部门工作台账标准化管理机制','当前部门各项工作记录分散在不同文档、聊天记录中，台账格式不统一，追溯、复盘困难，新人上手慢。\n\n统一台账模板，明确台账填写规范、更新频次与责任人，定期组织台账自查。\n\n规范工作留痕，方便进度追踪与复盘，降低工作交接成本。','实现工作过程可追溯，减少信息断层，提升部门整体协同管理效率，降低工作遗漏风险。','IMPLEMENTING',9.00,NULL,'3','李四','2026-11-07 22:45:38','2026-11-12 16:58:31','manage','当前部门各项工作记录分散在不同文档、聊天记录中，台账格式不统一，追溯、复盘困难，新人上手慢。','统一台账模板，明确台账填写规范、更新频次与责任人，定期组织台账自查。','规范工作留痕，方便进度追踪与复盘，降低工作交接成本。','all','','其他业务部门推行标准化台账后，跨岗位交接耗时明显缩短。','综合管理组','0','NONE',NULL,NULL,NULL,'0',0,NULL,0,0,NULL,'0'),(30,'提案附件测试001','创意提案附件测试创意提案附件测试\n\n创意提案附件测试创意提案附件测试创意提案附件测试\n\n创意提案附件测试创意提案附件测试创意提案附件测试创意提案附件测试','测试测试测试','PENDING_L1',0.00,NULL,'sam','Sam','2026-11-12 16:48:36','2026-11-12 16:48:36','manage','创意提案附件测试创意提案附件测试','创意提案附件测试创意提案附件测试创意提案附件测试','创意提案附件测试创意提案附件测试创意提案附件测试创意提案附件测试','all','/profile/upload/2026/11/12/提案附件测试_20261112164733A008.xlsx','测试','测试测试','0','L1',NULL,NULL,NULL,'0',0,NULL,0,0,'2026-11-19 16:48:36','0');
/*!40000 ALTER TABLE `bbs_idea_proposal` ENABLE KEYS */;
DROP TABLE IF EXISTS `bbs_idea_review`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bbs_idea_review` (
  `review_id` bigint NOT NULL AUTO_INCREMENT,
  `idea_id` bigint NOT NULL,
  `reviewer_user_id` varchar(64) NOT NULL,
  `reviewer_nick_name` varchar(100) DEFAULT NULL,
  `score` int NOT NULL,
  `comment` varchar(1000) DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `stage` varchar(20) DEFAULT 'L1' COMMENT '评审环节(L1/L2/L3)',
  `action` varchar(20) DEFAULT 'pass' COMMENT '评审动作(pass/reject/project)',
  `reject_reason` varchar(1000) DEFAULT NULL COMMENT '驳回原因',
  `is_visible_to_all` char(1) DEFAULT '0' COMMENT '意见是否对全员可见(0否1是)',
  `review_time` datetime DEFAULT NULL COMMENT '审核时间',
  PRIMARY KEY (`review_id`),
  KEY `idx_idea_review_idea` (`idea_id`),
  KEY `idx_idea_review_user` (`reviewer_user_id`),
  KEY `idx_idea_review_stage` (`stage`),
  CONSTRAINT `fk_idea_review_idea` FOREIGN KEY (`idea_id`) REFERENCES `bbs_idea_proposal` (`idea_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=51 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Innovation reviews';
/*!40101 SET character_set_client = @saved_cs_client */;

