CREATE TABLE `bbs_idea_stage_reviewer_config` (
  `config_id` bigint NOT NULL AUTO_INCREMENT,
  `stage_code` varchar(20) NOT NULL COMMENT 'L1/L2/L3',
  `stage_name` varchar(50) NOT NULL COMMENT '初审/复审/终审',
  `role_keys` varchar(1000) NOT NULL COMMENT '角色标识，逗号分隔',
  `status` char(1) NOT NULL DEFAULT '0' COMMENT '0正常 1停用',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  `reviewer_user_ids` varchar(500) DEFAULT NULL COMMENT '指定处理人用户ID，逗号分隔，与role_keys并集判断',
  PRIMARY KEY (`config_id`),
  UNIQUE KEY `uk_idea_stage_code` (`stage_code`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='创意提案流程评审角色配置';
