DROP TABLE IF EXISTS `bbs_qa_answer`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bbs_qa_answer` (
  `answer_id` bigint NOT NULL AUTO_INCREMENT COMMENT '回答ID',
  `question_id` bigint NOT NULL COMMENT '关联问题ID',
  `parent_answer_id` bigint DEFAULT NULL COMMENT '父回答ID（追问/补充楼中楼）',
  `content` longtext NOT NULL COMMENT '回答内容（富文本）',
  `is_best` char(1) NOT NULL DEFAULT '0' COMMENT '是否最佳答案（0否 1是）',
  `like_count` int NOT NULL DEFAULT '0' COMMENT '点赞数',
  `answer_user_id` varchar(64) NOT NULL COMMENT '回答者用户ID',
  `answer_nick_name` varchar(100) DEFAULT NULL COMMENT '回答者昵称',
  `answer_avatar` varchar(500) DEFAULT NULL COMMENT '回答者头像',
  `answer_dept_name` varchar(100) DEFAULT NULL COMMENT '回答者部门',
  `del_flag` char(1) NOT NULL DEFAULT '0' COMMENT '删除标志（0存在 2删除）',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建者',
  `update_by` varchar(64) DEFAULT NULL COMMENT '更新者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`answer_id`),
  KEY `idx_question_id` (`question_id`),
  KEY `idx_answer_user_id` (`answer_user_id`),
  KEY `idx_is_best` (`is_best`)
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='企业问答-回答表';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `bbs_qa_answer` DISABLE KEYS */;
INSERT INTO `bbs_qa_answer` VALUES (1,1,NULL,'AI啥都能干，除了不能帮你领工资','1',7,'2','张三',NULL,NULL,'0','2',NULL,'2026-05-01 21:08:24','2026-11-08 23:24:33'),(2,1,NULL,'我不知道','0',1,'2','张三',NULL,NULL,'0','2',NULL,'2026-05-01 21:08:40','2026-05-01 21:24:06'),(3,1,NULL,'我也想知道','0',1,'2','张三',NULL,NULL,'0','2',NULL,'2026-05-01 21:08:59','2026-05-01 21:25:44'),(4,3,NULL,'明天肯定又是大晴天，我问过AI了','1',1,'3','李四',NULL,'研发部门','0','3',NULL,'2026-10-18 09:06:34','2026-11-08 23:24:15'),(5,3,NULL,'明天下大雨，我问雷公了','0',0,'3','李四',NULL,'研发部门','0','3',NULL,'2026-10-18 09:06:44','2026-10-18 09:10:10'),(6,3,NULL,'龙王说他也不知道','0',0,'3','李四',NULL,'研发部门','0','3',NULL,'2026-10-18 09:06:59','2026-10-18 09:10:10'),(7,2,NULL,'测试','1',0,'3','李四',NULL,'研发部门','0','3',NULL,'2026-10-18 09:11:16','2026-10-18 09:11:37'),(8,2,NULL,'测试2','0',0,'3','李四',NULL,'研发部门','0','3',NULL,'2026-10-18 09:11:21','2026-10-18 09:11:37'),(9,4,NULL,'如果页面开启 KeepAlive，onUnmounted 不会执行，需要在 onDeactivated 和 onBeforeUnmount 里同时清除定时器，同时保存 timerId 避免覆盖，也可以搭配 AbortController 取消请求。\nts\nlet timer = null\nconst clearTimer = () => {\n  timer && clearInterval(timer)\n  timer = null\n}\nonMounted(() => timer = setInterval(fun, 2000))\nonDeactivated(clearTimer)\nonBeforeUnmount(clearTimer)','1',2,'3','李四',NULL,'研发部门','0','3',NULL,'2026-11-04 01:02:26','2026-11-07 17:17:22'),(10,5,NULL,'111','0',0,'3','李四',NULL,'研发部门','0','3',NULL,'2026-11-06 18:45:59','2026-11-06 18:45:59'),(11,5,NULL,'111','0',0,'3','李四',NULL,'研发部门','0','3',NULL,'2026-11-06 18:46:13','2026-11-06 18:46:13'),(12,5,NULL,'111','0',0,'1','管理员',NULL,'研发部门','0','1',NULL,'2026-11-06 18:46:51','2026-11-06 18:46:51'),(13,5,NULL,'33','0',0,'l1reviewer','初审员',NULL,'研发部门','0','l1reviewer',NULL,'2026-11-06 18:47:07','2026-11-06 18:47:07'),(14,5,NULL,'444','0',0,'l2reviewer','复审员',NULL,'研发部门','0','l2reviewer',NULL,'2026-11-06 18:47:27','2026-11-06 18:47:27'),(15,5,NULL,'45','0',0,'l3reviewer','终审员',NULL,'研发部门','0','l3reviewer',NULL,'2026-11-06 18:48:01','2026-11-06 18:48:01'),(16,10,NULL,'可以加上搜索筛选，或者用分页懒加载，不用一次性把所有选项加载出来。','0',1,'4','王五',NULL,'测试部门','0','4',NULL,'2026-11-08 23:24:02','2026-11-12 16:54:27'),(17,12,NULL,'我们部门申请调休，是要上传加班记录截图作为佐证材料，和调休单一起提交审批。如果系统里已经自动同步加班数据，就不用额外上传截图了，可以先问下行政。','1',2,'3','李四',NULL,'研发部门','0','3',NULL,'2026-11-08 23:26:13','2026-11-12 16:59:34'),(18,10,NULL,'之前也遇到过类似问题，推荐两个方案：1. 下拉框增加搜索输入，用户输入关键词再过滤；2. 虚拟滚动，只渲染可视区域内的选项，避免 DOM 太多卡顿。如果业务允许，也可以拆成级联选择，先选大类再选子项。','0',0,'3','李四',NULL,'研发部门','0','3',NULL,'2026-11-08 23:27:04','2026-11-08 23:27:04'),(19,11,NULL,'测试回答111','0',1,'sam','Sam',NULL,'市场部门','0','sam',NULL,'2026-11-12 16:49:41','2026-11-12 16:49:44'),(20,12,NULL,'测试回答222','0',3,'sam','Sam',NULL,'市场部门','0','sam',NULL,'2026-11-12 16:49:58','2026-11-12 16:59:34'),(21,16,NULL,'我来回答测试','0',2,'3','李四',NULL,'研发部门','0','3',NULL,'2026-11-12 16:55:28','2026-11-12 22:33:22'),(22,16,NULL,'测试最佳答案','0',3,'4','王五',NULL,'测试部门','0','4',NULL,'2026-11-12 16:57:00','2026-11-12 22:33:19');
/*!40000 ALTER TABLE `bbs_qa_answer` ENABLE KEYS */;
DROP TABLE IF EXISTS `bbs_qa_question`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bbs_qa_question` (
  `question_id` bigint NOT NULL AUTO_INCREMENT COMMENT '问题ID',
  `title` varchar(200) NOT NULL COMMENT '问题标题',
  `content` longtext NOT NULL COMMENT '问题内容（富文本）',
  `category` varchar(50) NOT NULL DEFAULT 'tech' COMMENT '分类：tech技术/product产品/hr人事/admin行政/other其他',
  `reward_points` int NOT NULL DEFAULT '10' COMMENT '悬赏积分（提交时冻结）',
  `frozen_points` int NOT NULL DEFAULT '0' COMMENT '已冻结积分',
  `status` varchar(20) NOT NULL DEFAULT 'open' COMMENT '状态：open待解答/solved已解决/archived已归档/cancelled已撤销',
  `best_answer_id` bigint DEFAULT NULL COMMENT '最佳答案ID',
  `ask_user_id` varchar(64) NOT NULL COMMENT '提问者用户ID',
  `ask_nick_name` varchar(100) DEFAULT NULL COMMENT '提问者昵称',
  `ask_avatar` varchar(500) DEFAULT NULL COMMENT '提问者头像',
  `ask_dept_name` varchar(100) DEFAULT NULL COMMENT '提问者部门',
  `visibility_scope` varchar(20) NOT NULL DEFAULT 'all' COMMENT '可见范围：all全员/dept部门/specific指定人员',
  `visibility_extra` varchar(500) DEFAULT NULL COMMENT '可见范围额外数据（部门ID/用户ID列表）',
  `expiry_time` datetime DEFAULT NULL COMMENT '问题有效期',
  `close_time` datetime DEFAULT NULL COMMENT '关闭/解决时间',
  `archive_time` datetime DEFAULT NULL COMMENT '归档时间',
  `view_count` int NOT NULL DEFAULT '0' COMMENT '浏览数',
  `answer_count` int NOT NULL DEFAULT '0' COMMENT '回答数',
  `tags` varchar(500) DEFAULT NULL COMMENT '关键词标签（逗号分隔）',
  `del_flag` char(1) NOT NULL DEFAULT '0' COMMENT '删除标志（0存在 2删除）',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建者',
  `update_by` varchar(64) DEFAULT NULL COMMENT '更新者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`question_id`),
  KEY `idx_status` (`status`),
  KEY `idx_category` (`category`),
  KEY `idx_ask_user_id` (`ask_user_id`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='企业问答-问题表';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `bbs_qa_question` DISABLE KEYS */;
INSERT INTO `bbs_qa_question` VALUES (1,'悬赏提问测试001','现在的AI到底能做什么？','tech',10,10,'archived',1,'1','管理员',NULL,NULL,'dept',NULL,'2026-05-29 00:00:00','2026-05-01 21:24:06','2026-05-01 21:24:35',25,3,'测试,AI','0','1',NULL,'2026-05-01 21:07:44','2026-11-08 23:24:19',NULL),(2,'1231312','12312312313123123123132231','tech',20,20,'solved',7,'2','张三',NULL,NULL,'all',NULL,'2026-05-25 00:00:00','2026-10-18 09:11:37',NULL,14,2,'123','0','2',NULL,'2026-05-22 03:16:44','2026-11-12 16:54:54',NULL),(3,'你知道明天天气怎么样么','你知道明天天气怎么样么','other',40,40,'archived',4,'2','张三',NULL,'研发部门','all',NULL,'2026-10-19 00:00:00','2026-10-18 09:10:10','2026-10-18 09:10:17',13,3,'天气','0','2',NULL,'2026-10-18 09:02:00','2026-11-08 23:24:12',NULL),(10,'下拉选择框数据太多，怎么优化体验','下拉选项有上百条，直接全部加载卡顿，有哪些优化方案？','product',15,15,'open',NULL,'sam','Sam',NULL,'市场部门','all',NULL,NULL,NULL,NULL,9,2,'下拉组件,交互','0','sam',NULL,'2026-11-07 22:24:14','2026-11-12 16:54:22',NULL),(11,'Nginx怎么配置请求超时时间','部分接口处理较慢，经常出现 504 超时，请问在哪里修改超时配置？','tech',10,10,'open',NULL,'5','赵六',NULL,'测试部门','all',NULL,'2027-01-31 00:00:00',NULL,NULL,6,1,'Nginx,反向代理','0','5',NULL,'2026-11-07 22:26:19','2026-11-12 16:59:12',NULL),(12,'员工加班调休申请需要哪些审批材料','申请调休的时候，一般需要附带加班记录截图吗？','hr',8,8,'solved',17,'4','王五',NULL,'测试部门','all',NULL,NULL,'2026-11-12 16:59:34',NULL,13,2,'调休,考勤','0','4',NULL,'2026-11-07 22:28:04','2026-11-12 16:59:34',NULL),(16,'发起提问测试','提问测试提问测试提问测试','hr',2,2,'open',NULL,'sam','Sam',NULL,'市场部门','all',NULL,NULL,NULL,NULL,7,2,'测试','0','sam',NULL,'2026-11-12 16:44:26','2026-11-12 23:37:12',NULL);
